import json,html,sys
from pathlib import Path
root=Path(sys.argv[1]).resolve()
d=json.loads((root/'report.json').read_text())
rows=[]
for r in d['results']:
    versions=[{'file':r['filename'],'label':'Full ringtone','jump':None}]+[{'file':i['file'],'label':f"Interrupted at {i['seconds']}s",'jump':i['seconds']} for i in r['interruptions']]
    for v in versions:
        raw=(root/v['file']).read_bytes();a=memoryview(raw)[44:].cast('f');v['duration']=len(a)/44100
        top=[];bottom=[]
        for i in range(600):
            b=a[i*len(a)//600:(i+1)*len(a)//600];top.append(f'{i},{60-max(b)*55:.2f}');bottom.append(f'{i},{60-min(b)*55:.2f}')
        v['path']='M'+' L'.join(top+bottom[::-1])+' Z'
    rows.append({'name':r['name'],'ring':r['ring'],'preset':r['preset'],'peak':r['metrics']['peak'],'versions':versions,'endings':sum(n['naturalEndJump']>.005 for n in r['notes'])})
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Yama-bruh · VR audio audit</title>
<style>:root{color-scheme:dark;font:16px system-ui;background:#111617;color:#e5e9e4}body{max-width:1000px;margin:32px auto;padding:0 20px}h1{font-size:27px}h2{font-size:20px}p,li{line-height:1.5}a{color:#9bd8c1}.panel{background:#1a2321;border:1px solid #384741;border-radius:12px;padding:20px;margin:20px 0}button,select,input{font:inherit;color:inherit;background:#253331;border:1px solid #58706b;border-radius:6px;padding:8px}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #b9e6a6}.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center}svg{width:100%;height:120px;background:#101714}input[type=range]{width:100%;padding:0}table{width:100%;border-collapse:collapse}td,th{padding:8px;text-align:left;border-bottom:1px solid #34423d}.scroll{overflow:auto;max-height:440px}.muted{color:#a9b7b1;font-size:14px}#status{min-height:1.5em}</style>
<h1>Yama-bruh · VR audio audit</h1><p>32 sound uses · 31 Bank A patches · captured VR v0.4.6</p>
<div class="panel"><strong>Notification renderer findings</strong><ul><li>Short notes can end before their envelopes reach silence.</li><li>Pitch-scaled release tails can exceed the allocated buffer.</li><li>Switching sounds immediately stops the shared previous source.</li></ul><p class="muted">No full-scale exceedances in these renders. Measured discontinuities are not proof of audible clicks. VR spatial processing and physical playback were not captured.</p></div>
<div class="panel"><h2 id="name"></h2><div class="controls"><label>Recording <select id="version"></select></label><button id="jump">Before interruption</button></div><svg id="wave" viewBox="0 0 600 120" role="img" aria-label="Recording waveform"><path id="shape" fill="#8cb99e"></path><line id="head" stroke="white" stroke-width="2" y1="0" y2="120"></line></svg><input id="seek" type="range" min="0" step="0.001" value="0" aria-label="Seek recording"><div class="controls"><button id="play">Play</button><button id="stop">Stop</button><span id="time"></span><a id="download" download>Download WAV</a></div><p id="status" aria-live="polite">Ready</p><p id="detail" class="muted"></p></div>
<input id="search" type="search" placeholder="Find a VR sound" aria-label="Find a VR sound"><div class="scroll"><table><thead><tr><th>Sound</th><th>VR ring</th><th>Peak</th><th>Note-end jumps &gt;0.005</th></tr></thead><tbody id="rows"></tbody></table></div>
<details class="panel"><summary>Evidence and scope</summary><p>The full ringtone is rendered by the exact captured notification library. Interrupted versions join truncated old audio to a newly started copy, before spatial processing. They simulate source interruption; they are not live VR recordings.</p><p>Gem playback lasts about 0.875s, shorter than its 6.5s repeat interval. Other keyboard triggers can still interrupt it.</p><a href="findings.json">Findings</a> · <a href="report.json">Full measurements</a><p class="muted">No sound fixes or VR changes were deployed.</p></details>
<script>const rows=__DATA__;
const el=id=>document.getElementById(id);let current,version,ctx,buffer,source,offset=0,started=0,playing=false,generation=0;
function position(){return playing?Math.min(version.duration,offset+ctx.currentTime-started):offset;}
function pause(){offset=position();playing=false;if(source){source.onended=null;source.stop();source=null;}el('play').textContent='Play';}
function chooseVersion(i){if(version)pause();generation++;offset=0;buffer=null;version=current.versions[i];el('shape').setAttribute('d',version.path);el('seek').max=version.duration;el('download').href=version.file;el('jump').disabled=version.jump===null;el('status').textContent='Ready';}
function choose(r){current=r;el('name').textContent=r.name+' · '+r.ring;el('detail').textContent='Preset '+r.preset+' · full ringtone peak '+r.peak.toFixed(3);el('version').replaceChildren();r.versions.forEach((v,i)=>{let o=document.createElement('option');o.value=i;o.textContent=v.label;el('version').append(o);});chooseVersion(0);}
async function play(){let g=generation;el('status').textContent='Loading…';el('play').disabled=true;try{ctx ||= new AudioContext();await ctx.resume();if(!buffer){const response=await fetch(version.file);if(!response.ok)throw Error('Recording unavailable');let decoded=await ctx.decodeAudioData(await response.arrayBuffer());if(g!==generation)return;buffer=decoded;}if(offset>=version.duration)offset=0;source=ctx.createBufferSource();source.buffer=buffer;source.connect(ctx.destination);started=ctx.currentTime;playing=true;source.onended=()=>{playing=false;offset=0;source=null;el('play').textContent='Play';el('status').textContent='Finished';};source.start(0,offset);el('play').textContent='Pause';el('status').textContent='Playing';}catch(e){el('status').textContent='Could not play: '+e.message;}finally{el('play').disabled=false;}}
function seek(t){let resume=playing;pause();offset=Math.max(0,Math.min(version.duration,t));if(resume)play();}
el('play').onclick=()=>{if(playing){pause();el('status').textContent='Paused';}else play();};el('stop').onclick=()=>{generation++;pause();offset=0;el('status').textContent='Stopped';};el('seek').oninput=()=>seek(Number(el('seek').value));el('version').onchange=()=>chooseVersion(Number(el('version').value));el('jump').onclick=()=>seek(version.jump-.15);
function list(){el('rows').replaceChildren();for(const r of rows.filter(r=>(r.name+' '+r.ring).toLowerCase().includes(el('search').value.toLowerCase()))){let tr=document.createElement('tr'),td=document.createElement('td'),b=document.createElement('button');b.textContent=r.name;b.onclick=()=>choose(r);td.append(b);tr.append(td);for(const v of [r.ring,r.peak.toFixed(3),r.endings]){let c=document.createElement('td');c.textContent=v;tr.append(c);}el('rows').append(tr);}}
function tick(){const t=position();el('seek').value=t;el('time').textContent=t.toFixed(2)+' / '+version.duration.toFixed(2)+' s';for(const a of ['x1','x2'])el('head').setAttribute(a,t/version.duration*600);requestAnimationFrame(tick);}el('search').oninput=list;list();choose(rows.find(r=>r.ring==='gem'));tick();</script></html>'''
(root/'index.html').write_text(page.replace('__DATA__',json.dumps(rows).replace('</','<\\/')))
